        for (int i = 1; i <= n && !f1; ++i)
            for (int j = 1; j <= n && !f1; ++j)
                for (int k = 1; k <= 6 && !f1; ++k)
                    for (int l = 1; l <= 6; ++l)
                        if (a[i][k] * 10 + a[j][l] == m ||
                            a[i][k] + a[j][l] * 10 == m) {
                            f1 = 1;
                            break;
                        }

        f = f1;
    }

    cout << m - 1;
    return 0;
}

